//! Application icon.
//!
//! Single source — `assets/app-icon.png` (512×512 RGBA). `build.rs` scales
//! it down to 32×32 for the tray (file `tray-32.rgba` in `OUT_DIR`) and builds the `.ico`
//! for the exe resource from the same pixels.

use tray_icon::Icon;

/// 32×32 RGBA frame generated by the build from `assets/app-icon.png`.
const TRAY_ICON_RGBA: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/tray-32.rgba"));
/// Side length of the tray frame.
const TRAY_ICON_SIZE: u32 = 32;

/// Application icon for the tray.
pub fn get_icon() -> Icon {
    Icon::from_rgba(TRAY_ICON_RGBA.to_vec(), TRAY_ICON_SIZE, TRAY_ICON_SIZE).unwrap_or_else(|_| {
        // Fallback for a corrupted frame: a 1×1 white pixel.
        Icon::from_rgba(vec![255; 4], 1, 1).unwrap()
    })
}
